def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker_cols = {}
    marker_top = {}
    # Vertical marker columns reach the bottom edge; preserve the marker itself.
    for c in range(w):
        if grid[h - 1][c] == 0:
            continue
        color = grid[h - 1][c]
        r = h - 1
        while r >= 0 and grid[r][c] == color:
            r -= 1
        marker_cols[c] = color
        marker_top[c] = r + 1
    # Every horizontal bar has a one-cell gap at a beam column; the bar's
    # color fills from the preceding bar down through this bar.
    for c in marker_cols:
        events = []
        for r, row in enumerate(grid):
            if row[c] != 0:
                continue
            left = next((row[k] for k in range(c - 1, -1, -1) if row[k]), 0)
            right = next((row[k] for k in range(c + 1, w) if row[k]), 0)
            if left and left == right:
                events.append((r, left))
        events.sort()
        previous = -1
        last_color = None
        for r, color in events:
            for rr in range(previous + 1, r + 1):
                if out[rr][c] == 0:
                    out[rr][c] = color
            previous = r
            last_color = color
        if last_color is not None:
            for rr in range(previous + 1, marker_top[c]):
                if out[rr][c] == 0:
                    out[rr][c] = last_color
    return out
